// your random seed
let seed = generate_seed_from_token_data(tokenData);

// the ID of the token
let tokenId = parseInt(tokenData.tokenId.substring(2))

rnd = new Random(seed);

function generate_seed_from_token_data(token) {
    return parseInt(token.hash.slice(0, 16), 16)
}

function setup_params_from_token(token) {
    let hashPairs = []
    for (let j = 0; j < 32; j++) {
        hashPairs.push(token.hash.slice(2 + (j * 2), 4 + (j * 2)))
    }
    return hashPairs.map(x => {
        return parseInt(x, 16)
    })
}

function calculateFeatures(tokenData) {
    let p = setup_params_from_token(tokenData), pid = 0;
    let pick_using_param = (choices, param) => choices[parseInt(map(param, 0, 256, 0, choices.length))];

    let feats = {};

    feats.texture = pick_using_param(["gradient", "plain"], p[pid++]);
    feats.reflection = pick_using_param(["yes", "no", "no", "no"], p[pid++]);
    feats.colors = pick_using_param(SAMPLE_COLOR_OPS, p[pid++]);
    feats.palette = palette_names[pick_using_param([...Array(palettes.length).keys()], p[pid++])];
    feats.bg_style = bg_style_names[pick_using_param([...Array(4).keys()], p[pid++])];

    generate_masks_colors_noise(feats.colors);
    feats.subject = category_names[infer_category()];

    return feats;
}

