    Weights[6] = [[239,-372,224,2,-5,-326,-384,51,322,-242,0,8,-9,12,-474,-228,7,905,-45,637,921,-349,-768,153,-384,-235,162,-354,-1,-3,-128,967],[-367,375,304,-7,-7,-30,-746,195,-306,-350,-8,7,-2,-124,-92,-75,-5,138,123,471,551,-66,-34,-319,-173,30,-115,274,-5,-7,110,545],[258,1054,-355,0,-4,322,-507,456,-504,-92,2,9,8,46,34,289,-8,101,-195,520,76,-538,408,252,292,128,31,835,-3,-6,-509,-318]]
    Bias[0] = [-77,-55,-0,57,117,242,42,70,-185,260,231,97,29,111,113,-232,-73,39,89,82,135,51,-4,-169,-146,60,-31,61,153,-215,258,188]
    Bias[1] = [-42,-83,-127,-11,130,-344,-4,106,-136,181,-241,220,-6,-289,-194,455,94,-318,188,-95,218,-118,-48,-15,-56,-115,17,133,171,126,-30,22]
