// From https://stackoverflow.com/questions/1669190/find-the-min-max-element-of-an-array-in-javascript
Array.prototype.max = function() {
    return Math.max.apply(null, this);
};
Array.prototype.min = function() {
    return Math.min.apply(null, this);
};

// From https://stackoverflow.com/questions/2963281/javascript-algorithm-to-find-elements-in-array-that-are-not-in-another-array
function setdiff(a1, a2) {
    // console.log(a1)
    // console.log(a2)
    // console.log(a2.filter(x => !a1.includes(x)) )
    return a2.filter(x => !a1.includes(x))
}

function generate_masks_colors_noise(color_style) {
    /*************************************************************************
     * Generate pattern of masks and colors
     *************************************************************************/
    let pattern_so_far = new Array(), color_pattern_so_far = new Array();

    // generate pattern of masks and colors
    for (var i = 0; i < mask_model.length; i++) {
        if (color_style == CLR_FROM_MODEL) {
            if (i == 0) {
                pattern[i] = rnd.random_choice(mask_model[i]);
            } else {
                pattern[i] = rnd.random_choice(setdiff(pattern_so_far, mask_model[i][pattern[i - 1]]));
            }
            if (i == 0) {
                color_pattern[i] = rnd.random_choice(color_model[pattern[i] - 1]);
            } else {
                color_pattern[i] = rnd.random_choice(setdiff(color_pattern_so_far, color_model[pattern[i] - 1]));
            }
            pattern[i] = pattern[i] - 1;
            color_pattern[i] = color_pattern[i] - 1;
            pattern_so_far.push(pattern[i] + 1);
            color_pattern_so_far.push(color_pattern[i] + 1);
        } else if (color_style == CLR_UNIFORM) {
            if (i == 0) {
                pattern[i] = round(rnd.random_dec() * (masks.length - 1));
            } else {
                pattern[i] = rnd.random_choice(setdiff(pattern, [...Array(masks.length).keys()]));
            }
            if (i == 0) {
                color_pattern[i] = round(rnd.random_dec() * (num_colors_per_palette - 1));
            } else {
                color_pattern[i] = rnd.random_choice(setdiff(color_pattern, [...Array(num_colors_per_palette).keys()]))
            }
        }

        // The shape prototypes are the prototypes themselves (25), and their flipped versions (25 more). So if the shape id is >25, need to subtract 25 and use its flipped version.
        if (pattern[i] > (num_prototypes - 1)) {
            mask_gen[i] = reshape(masks[pattern[i] - num_prototypes], Nx, Ny)
            mask_gen_use = new Array
            for (var cuse = 0; cuse < mask_gen[i].length; cuse++) {
                mask_gen_use[cuse] = mask_gen[i][mask_gen[i].length - cuse - 1];
            }
            mask_gen[i] = mask_gen_use;
        } else {
            mask_gen[i] = reshape(masks[pattern[i]], Nx, Ny)
        }
    }

    // noise_vector = [-0.1476, 0.0409, -0.0298]; // test vector to match MATLAB implementation
    for (var k = 0; k < mask_model.length; k++) {
        noise_vector[k] = new Array();
        for (var n = 0; n < min_noise.length; n++) {
            noise_vector[k][n] = rnd.random_num(min_noise[n] / precision, max_noise[n] / precision);
        }
    }
    /*************************************************************************/
}

function infer_category() {
    // predict category using classifier saved in model.js: landscape, flower, urban, bird
    let pred_scene = new Array();
    for (var i = 0; i < num_categories; i++) {
        pred_scene[i] = rnd.random_dec() * 0.00001;
        for (var k = 0; k < pattern.length; k++) {
            pred_scene[i] = pred_scene[i] + pfgc[pattern[k]][k][i];
        }
    }
    return pred_scene.indexOf(max(pred_scene));
}